INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000315,'challenges','{"id":760300000000315,"title":"B1 · Литературный · Автор и персонажи · Challenge 15","description":"B1: автор и персонажи. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Автор и персонажи","track":"Литературный","topic":"Автор и персонажи","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «descriptive language».","options":["точка зрения","образный язык описания","литературный жанр","символическая деталь"],"correctAnswer":"образный язык описания","explanation":"«descriptive language» — «образный язык описания»."},{"id":2,"question":"Какое выражение на британском английском соответствует «неожиданный финал»?","options":["plot twist","character development","unexpected ending","emotional response"],"correctAnswer":"unexpected ending","explanation":"«unexpected ending» — «неожиданный финал»."},{"id":3,"question":"Выбери точное русское значение выражения «author''s intention».","options":["символическая деталь","намерение автора","сюжетный поворот","точка зрения"],"correctAnswer":"намерение автора","explanation":"«author''s intention» — «намерение автора»."},{"id":4,"question":"Выбери точное русское значение выражения «central theme».","options":["центральная тема","образный язык описания","неожиданный финал","точка зрения"],"correctAnswer":"центральная тема","explanation":"«central theme» — «центральная тема»."},{"id":5,"question":"Какое выражение на британском английском соответствует «развитие персонажа»?","options":["point of view","character development","plot twist","compare two texts"],"correctAnswer":"character development","explanation":"«character development» — «развитие персонажа»."},{"id":6,"question":"Выбери точное русское значение выражения «compare two texts».","options":["намерение автора","сравнить два текста","образный язык описания","эмоциональный отклик"],"correctAnswer":"сравнить два текста","explanation":"«compare two texts» — «сравнить два текста»."},{"id":7,"question":"Выбери точное русское значение выражения «symbolic detail».","options":["сюжетный поворот","символическая деталь","развитие персонажа","сравнить два текста"],"correctAnswer":"символическая деталь","explanation":"«symbolic detail» — «символическая деталь»."},{"id":8,"question":"Какое выражение на британском английском соответствует «сюжетный поворот»?","options":["plot twist","descriptive language","unexpected ending","literary genre"],"correctAnswer":"plot twist","explanation":"«plot twist» — «сюжетный поворот»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 36 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
