ения «author''s intention».","options":["образный язык описания","символическая деталь","литературный жанр","намерение автора"],"correctAnswer":"намерение автора","explanation":"«author''s intention» — «намерение автора»."},{"id":7,"question":"Выбери точное русское значение выражения «compare two texts».","options":["образный язык описания","литературный жанр","эмоциональный отклик","сравнить два текста"],"correctAnswer":"сравнить два текста","explanation":"«compare two texts» — «сравнить два текста»."},{"id":8,"question":"Какое выражение на британском английском соответствует «точка зрения»?","options":["emotional response","point of view","descriptive language","literary genre"],"correctAnswer":"point of view","explanation":"«point of view» — «точка зрения»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 39 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000322,'challenges','{"id":760300000000322,"title":"B2 · Литературный · Образность и стиль · Challenge 22","description":"B2: образность и стиль. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":41,"category":"Образность и стиль","track":"Литературный","topic":"Образность и стиль","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «literary criticism».","options":["мотивация персонажа","неоднозначный финал","символические образы","литературная критика"],"correctAnswer":"литературная критика","explanation":"«literary criticism» — «литературная критика»."},{"id":2,"question":"Какое выражение на британском английском соответствует «ненадёжный рассказчик»?","options":["symbolic imagery","tone and register","unreliable narrator","interpret a metaphor"],"correctAnswer":"unreliable narrator","explanation":"«unreliable narrator» — «ненадёжный рассказчик»."},{"id":3,"question":"Выбери точное русское значение выражения «interpret a metaphor».","options":["символические образы","исторический контекст","повествовательная перспектива","истолковать метафору"],"correctAnswer":"истолковать метафору","explanation":"«interpret a metaphor» — «истолковать метафору»."},{"id":4,"question":"Выбери точное русское значение выражения «ambiguous ending».","options":["символические образы","исторический контекст","истолковать метафору","неоднозначный финал"],"correctAnswer":"неоднозначный финал","explanation":"«ambiguous ending» — «неоднозначный финал»."},{"id":5,"question":"Какое выражение на британском английском соответствует «мотивация персонажа»?","options":["symbolic imagery","character motivation","literary criticism","interpret a metaphor"],"correctAnswer":"character motivation","explanation":"«character motivation» — «мотивация персонажа»."},{"id":6,"question":"Выбери точное русское значение выражения «dramatic irony».","options":["драматическая ирония","литературная критика","ненадёжный рассказчик","символические образы"],"correctAnswer":"драматическая ирония","explanation":"«dramatic irony» — «драматическая ирония»."},{"id":7,"question":"Выбери точное русское значение выражения «historical context».","options":["тон и стиль речи","исторический контекст","символические образы","литературная критика"],"correctAnswer":"исторический контекст","explanation":"«historical context» — «исторический контекст»."},{"id":8,"question":"Какое выражение на британском английском соответствует «образный язык»?","options":["dramatic irony","figurative language","ambiguous ending","tone and register"],"correctAnswer":"figurative language","explanation":"«figurative language» — «образный язык»."}],"durationMinutes":10,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 41 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000323,'challenges','{"id":760300000000323,"title":"C1 · Литературный · Образность и стиль · Challenge 23","description":"C1: образность и стиль. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Образность и стиль","track":"Литературный","topic":"Образность и стиль","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «shift in narrative focus».","options":["литературная аллюзия","межтекстовая отсылка","смена фокуса повествования","подтекстовый смысл"],"correctAnswer":"смена фокуса повествования","explanation":"«shift in narrative focus» — «смена фокуса повествования»."},{"id":2,"question":"Какое выражение на британском английском соответствует «тематическая целостность»?","options":["literary allusion","thematic coherence","subtextual meaning","intertextual reference"],"correctAnswer":"thematic coherence","explanation":"«thematic coherence» — «тематическая целостность»."},{"id":3,"question":"Выбери точное русское значение выражения «narrative ambiguity».","options":["косвенная характеристика персонажа","стилистический контраст","повествовательная неоднозначность","авторский голос"],"correctAnswer":"повествовательная неоднозначность","explanation":"«narrative ambiguity» — «повествовательная неоднозначность»."},{"id":4,"question":"Выбери точное русское значение выражения «intertextual reference».","options":["межтекстовая отсылка","смена фокуса повествования","повествовательная неоднозначность","подтекстовый смысл"],"correctAnswer":"межтекстовая отсылка","explanation":"«intertextual reference» — «межтекстовая отсылка»."},{"id":5,"question":"Какое выражение на британском английском соответствует «подтекстовый смысл»?","options":["subtextual meaning","authorial voice","implicit characterisation","narrative ambiguity"],"correctAnswer":"s