INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000324,'challenges','{"id":760300000000324,"title":"C2 · Литературный · Образность и стиль · Challenge 24","description":"C2: образность и стиль. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":51,"category":"Образность и стиль","track":"Литературный","topic":"Образность и стиль","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «discursive ambiguity».","options":["дискурсивная неоднозначность","полифоническое повествование","риторическая непрямота","подрывная интертекстуальность"],"correctAnswer":"дискурсивная неоднозначность","explanation":"«discursive ambiguity» — «дискурсивная неоднозначность»."},{"id":2,"question":"Какое выражение на британском английском соответствует «метаповествовательный приём»?","options":["subversive intertextuality","self-reflexive prose","polyphonic narrative","metafictional device"],"correctAnswer":"metafictional device","explanation":"«metafictional device» — «метаповествовательный приём»."},{"id":3,"question":"Выбери точное русское значение выражения «sustained allegory».","options":["полифоническое повествование","герменевтическая интерпретация","сквозная аллегория","метаповествовательный приём"],"correctAnswer":"сквозная аллегория","explanation":"«sustained allegory» — «сквозная аллегория»."},{"id":4,"question":"Выбери точное русское значение выражения «hermeneutic interpretation».","options":["фокализация повествования","риторическая непрямота","герменевтическая интерпретация","саморефлексивная проза"],"correctAnswer":"герменевтическая интерпретация","explanation":"«hermeneutic interpretation» — «герменевтическая интерпретация»."},{"id":5,"question":"Какое выражение на британском английском соответствует «риторическая непрямота»?","options":["rhetorical indirection","narrative focalisation","metafictional dev