INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000326,'challenges','{"id":760300000000326,"title":"A2 · Литературный · Анализ текста · Challenge 26","description":"A2: анализ текста. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":34,"category":"Анализ текста","track":"Литературный","topic":"Анализ текста","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «main character».","options":["короткий рассказ","другое место действия","интересный сюжет","главный персонаж"],"correctAnswer":"главный персонаж","explanation":"«main character» — «главный персонаж»."},{"id":2,"question":"Какое выражение на британском английском соответствует «голос повествователя»?","options":["narrative voice","different setting","poetry collection","describe a place"],"correctAnswer":"narrative voice","explanation":"«narrative voice» — «голос повествователя»."},{"id":3,"question":"Выбери точное русское значение выражения «short story».","options":["читать вслух","счастливый конец","короткий рассказ","имя автора"],"correctAnswer":"короткий рассказ","explanation":"«short story» — «короткий рассказ»."},{"id":4,"question":"Выбери точное русское значение выражения «author''s name».","options":["счастливый конец","интересный сюжет","главный персонаж","имя автора"],"correctAnswer":"имя автора","explanation":"«author''s name» — «имя автора»."},{"id":5,"question":"Какое выражение на британском английском соответствует «написать абзац»?","options":["narrative voice","book review","different setting","write a paragraph"],"correctAnswer":"write a paragraph","explanation":"«write a paragraph» — «написать абзац»."},{"id":6,"question":"Выбери точное русское значение выражения «happy ending».","options":["голос повествователя","читать вслух","счастливый конец","главный персонаж"],"correctAnswer":"счастливый конец","explanation":"«happy ending» — «счастливый конец»."},{"id":7,"question":"Выбери точное русское значение выражения «interesting plot».","options":["голос повествователя","интересный сюжет","короткий рассказ","описать место"],"correctAnswer":"интересный сюжет","explanation":"«interesting plot» — «интересный сюжет»."},{"id":8,"question":"Какое выражение на британском английском соответствует «другое место действия»?","options":["describe a place","main character","narrative voice","different setting"],"correctAnswer":"different setting","explanation":"«different setting» — «другое место действия»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 34 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
