INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000328,'challenges','{"id":760300000000328,"title":"B2 · Литературный · Анализ текста · Challenge 28","description":"B2: анализ текста. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":41,"category":"Анализ текста","track":"Литературный","topic":"Анализ текста","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «dramatic irony».","options":["символические образы","образный язык","неоднозначный финал","драматическая ирония"],"correctAnswer":"драматическая ирония","explanation":"«dramatic irony» — «драматическая ирония»."},{"id":2,"question":"Какое выражение на британском английском соответствует «образный язык»?","options":["dramatic irony","narrative perspective","figurative language","underlying theme"],"correctAnswer":"figurative language","explanation":"«figurative language» — «образный язык»."},{"id":3,"question":"Выбери точное русское значение выражения «ambiguous ending».","options":["драматическая ирония","истолковать метафору","повествовательная перспектива","неоднозначный финал"],"correctAnswer":"неоднозначный финал","explanation":"«ambiguous ending» — «неоднозначный финал»."},{"id":4,"question":"Выбери точное русское значение выражения «character motivation».","options":["истолковать метафору","мотивация персонажа","исторический контекст","тон и стиль речи"],"correctAnswer":"мотивация персонажа","explanation":"«character motivation» — «мотивация персонажа»."},{"id":5,"question":"Какое выражение на британском английском соответствует «исторический контекст»?","options":["character motivation","narrative perspective","tone and register","historical context"],"correctAnswer":"historical context","explanation":"«historical context» — «исторический контекст»."},{"id":6,"question":"Выбери точное русское значение выражения «literary criticism».","options":["истолковать метафору","литературная критика","сквозная тема","драматическая ирония"],"correctAnswer":"литературная критика","explanation":"«literary criticism» — «литературная критика»."},{"id":7,"question":"Выбери точное русское значение выражения «unreliable narrator».","options":["ненадёжный рассказчик","образный язык","литературная критика","символические образы"],"correctAnswer":"ненадёжный рассказчик","explanation":"«unreliable narrator» — «ненадёжный рассказчик»."},{"id":8,"question":"Какое выражение на британском английском соответствует «истолковать метафору»?","options":["interpret a metaphor","unreliable narrator","symbolic imagery","figurative language"],"correctAnswer":"interpret a metaphor","explanation":"«interpret a metaphor» — «истолковать метафору»."}],"durationMinutes":10,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 41 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000329,'challenges','{"id":760300000000329,"title":"C1 · Литературный · Анализ текста · Challenge 29","description":"C1: анализ текста. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Анализ текста","track":"Литературный","topic":"Анализ текста","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «intertextual reference».","options":["межтекстовая отсылка","критическая интерпретация","стилистический контраст","тематическая целостность"],"correctAnswer":"межтекстовая отсылка","explanation":"«intertextual reference» — «межтекстовая отсылка»."},{"id":2,"question":"Какое выражение на британском английском соответствует «литературная аллюзия»?","options":["literary allusion","narrative ambiguity","intertextual reference","ironic understatement"],"correctAnswer":"literary allusion","explanation":"«literary allusion» — «литературная аллюзия»."},{"id":3,"question":"Выбери точное русское значение выражения «ironic understatement».","options":["смена фокуса повествования","критическая интерпретация","повествовательная неоднозначность","ироническое преуменьшение"],"correctAnswer":"ироническое преуменьшение","explanation":"«ironic understatement» — «ироническое преуменьшение»."},{"id":4,"question":"Выбери точное русское значение выражения «authorial voice».","options":["повествовательная неоднозначность","тематическая целостность","развёрнутая метафора","авторский голос"],"correctAnswer":"авторский голос","explanation":"«authorial voice» — «авторский голос»."},{"id":5,"question":"Какое выражение на британском английском соответствует «критическая интерпретация»?","options":["critical interpretation","literary allusion","shift in narrative focus","authorial voice"],"correctAnswer":"critical interpretation","explanation":"«critical interpretatio