INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000341,'challenges','{"id":760300000000341,"title":"C1 · Литературный · Описание и повествование · Challenge 41","description":"C1: описание и повествование. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":49,"category":"Описание и повествование","track":"Литературный","topic":"Описание и повествование","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «thematic coherence».","options":["межтекстовая отсылка","смена фокуса повествования","тематическая целостность","стилистический контраст"],"correctAnswer":"тематическая целостность","explanation":"«thematic coherence» — «тематическая целостность»."},{"id":2,"question":"Какое выражение на британском английском соответствует «критическая интерпретация»?","options":["shift in narrative focus","critical interpretation","intertextual reference","stylistic contrast"],"correctAnswer":"critical interpretation","explanation":"«critical interpretation» — «критическая интерпретация»."},{"id":3,"question":"Выбери точное русское значение выражения «literary allusion».","options":["ироническое преуменьшение","развёрнутая метафора","авторский голос","литературная аллюзия"],"correctAnswer":"литературная аллюзия","explanation":"«literary allusion» — «литературная аллюзия»."},{"id":4,"question":"Выбери точное русское значение выражения «extended metaphor».","options":["авторский голос","развёрнутая метафора","подтекстовый смысл","стилистический контраст"],"correctAnswer":"развёрнутая метафора","explanation":"«extended metaphor» — «развёрнутая метафора»."},{"id":5,"question":"Какое выражение на британском английском соответствует «межтекстовая отсылка»?","options":["extended metaphor","authorial voice","intertextual reference","critical interpretation"],"correctAnswer":"intertextual reference","explanation":"«inte