ателя","explanation":"«narrative voice» — «голос повествователя»."},{"id":7,"question":"Выбери точное русское значение выражения «book review».","options":["описать место","читать вслух","главный персонаж","отзыв о книге"],"correctAnswer":"отзыв о книге","explanation":"«book review» — «отзыв о книге»."},{"id":8,"question":"Какое выражение на британском английском соответствует «другое место действия»?","options":["book review","different setting","narrative voice","main character"],"correctAnswer":"different setting","explanation":"«different setting» — «другое место действия»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 31 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000345,'challenges','{"id":760300000000345,"title":"B1 · Литературный · Автор и персонажи · Challenge 45","description":"B1: автор и персонажи. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Автор и персонажи","track":"Литературный","topic":"Автор и персонажи","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «author''s intention».","options":["точка зрения","неожиданный финал","структура повествования","намерение автора"],"correctAnswer":"намерение автора","explanation":"«author''s intention» — «намерение автора»."},{"id":2,"question":"Какое выражение на британском английском соответствует «эмоциональный отклик»?","options":["unexpected ending","symbolic detail","emotional response","character development"],"correctAnswer":"emotional response","explanation":"«emotional response» — «эмоциональный отклик»."},{"id":3,"question":"Выбери точное русское значение выражения «literary genre».","options":["эмоциональный отклик","литературный жанр","развитие персонажа","неожиданный финал"],"correctAnswer":"литературный жанр","explanation":"«literary genre» — «литературный жанр»."},{"id":4,"question":"Выбери точное русское значение выражения «point of view».","options":["литературный жанр","точка зрения","неожиданный финал","сюжетный поворот"],"correctAnswer":"точка зрения","explanation":"«point of view» — «точка зрения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «образный язык описания»?","options":["unexpected ending","descriptive language","character development","plot twist"],"correctAnswer":"descriptive language","explanation":"«descriptive language» — «образный язык описания»."},{"id":6,"question":"Выбери точное русское значение выражения «unexpected ending».","options":["неожиданный финал","символич