INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000346,'challenges','{"id":760300000000346,"title":"B2 · Литературный · Автор и персонажи · Challenge 46","description":"B2: автор и персонажи. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":44,"category":"Автор и персонажи","track":"Литературный","topic":"Автор и персонажи","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «historical context».","options":["тон и стиль речи","исторический контекст","образный язык","истолковать метафору"],"correctAnswer":"исторический контекст","explanation":"«historical context» — «исторический контекст»."},{"id":2,"question":"Какое выражение на британском английском соответствует «тон и стиль речи»?","options":["dramatic irony","narrative perspective","figurative language","tone and register"],"correctAnswer":"tone and register","explanation":"«tone and register» — «тон и стиль речи»."},{"id":3,"question":"Выбери точное русское значение выражения «ambiguous ending».","options":["неоднозначный финал","мотивация персонажа","повествовательная перспектива","ненадёжный рассказчик"],"correctAnswer":"неоднозначный финал","explanation":"«ambiguous ending» — «неоднозначный финал»."},{"id":4,"question":"Выбери точное русское значение выражения «symbolic imagery».","options":["исторический контекст","мотивация персонажа","неоднозначный финал","символические образы"],"correctAnswer":"символические образы","explanation":"«symbolic imagery» — «символические образы»."},{"id":5,"question":"Какое выражение на британском английском соответствует «литературная критика»?","options":["unreliable narrator","literary criticism","dramatic irony","figurative language"],"correctAnswer":"literary criticism","explanation":"«literary criticism» — «литературная критика»."},{"id":6,"question":"Выбери точное русское значение выражения «interpret a metaphor».","options":["драматическая ирония","неоднозначный финал","ненадёжный рассказчик","истолковать метафору"],"correctAnswer":"истолковать метафору","explanation":"«interpret a metaphor» — «истолковать метафору»."},{"id":7,"question":"Выбери точное русское значение выражения «narrative perspective».","options":["символические образы","исторический контекст","сквозная тема","повествовательная перспектива"],"correctAnswer":"повествовательная перспектива","explanation":"«narrative perspective» — «повествовательная перспектива»."},{"id":8,"question":"Какое выражение на британском английском соответствует «мотивация персонажа»?","options":["figurative language","underlying theme","dramatic irony","character motivation"],"correctAnswer":"character motivation","explanation":"«character motivation» — «мотивация персонажа»."}],"durationMinutes":10,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 44 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
